# frozen_string_literal: true

# Builds representation-vectors.json from the source-*.json documents in this
# directory, using DppRepresentation and ElementIdPath of this repository:
#
#   ruby -Iapp/lib spec/fixtures/representation-vectors/generate.rb
#
# The vectors are the specification both implementations are tested against:
# spec/lib/representation_vectors_spec.rb here, test/representation_test.rb in
# pod-dpp, which carries a copy of this file. Regenerating is a deliberate
# change of that specification, and the copy in pod-dpp has to follow.
require "json"
require "active_support/core_ext/object/deep_dup"
require "dpp_representation"
require "element_id_path"

DIR = __dir__

PATHS = {
  "source-en18223.json" => [
    "$.performanceMetrics", "$.performanceMetrics.maxPressure", "$.performanceMetrics.efficiencyRatings",
    "$.performanceMetrics.efficiencyRatings[1]", "$.performanceMetrics.complexTraits[1].fieldTwo",
    "$.supportedVoltages[-1]", "$.userManual", "$.productDescription", "$.productDescription[0]",
    "$.granularity", "$.performanceMetrics.nope"
  ],
  "source-reference-000001.json" => [
    "$.ProductIdentification.ModelIdentifier", "$.EnergyPerformance", "$['EnergyPerformance']['LuminousFlux']"
  ],
  "source-lightbulb.json" => [
    "$.SubstancesOfConcern.MaterialComposition", "$.SubstancesOfConcern.MaterialComposition[1]",
    "$.SubstancesOfConcern.MaterialComposition[1].material",
    "$.DeclarationOfConformity", "$.LightQuality.Dimmable"
  ]
}.freeze

cases = PATHS.map do |file, paths|
  full = JSON.parse(File.read(File.join(DIR, file)))
  {
    "name" => File.basename(file, ".json").delete_prefix("source-"),
    "full" => full,
    "compressed" => DppRepresentation.passport(full, "compressed"),
    "elements" => paths.map do |path|
      node = ElementIdPath.parse(path).resolve(full)
      { "path" => path,
        "found" => !node.nil?,
        "full" => node,
        "compressed" => node.nil? ? nil : DppRepresentation.element(node, "compressed", document: full) }
    end
  }
end

vectors = {
  "description" => "full -> compressed (EN 18222:2026 8.1, EN 18223:2026 5.2 and Annex A); " \
                   "generated by generate.rb, see there",
  "valid" => DppRepresentation::VALUES,
  "default" => DppRepresentation::DEFAULT,
  "invalid" => ["", "bogus", "Full", "FULL", "Compressed", " full", "full ", "expanded"],
  "cases" => cases
}

File.write(File.join(DIR, "representation-vectors.json"), "#{JSON.pretty_generate(vectors)}\n")
puts "#{cases.size} cases, #{cases.sum { |c| c['elements'].size }} element paths"
